// ---- Mann-Whitney U 双侧检验 ----
// 无第三方依赖。小样本（合并样本数 N <= MW_EXACT_LIMIT）按秩和分布精确计算：
// 合并排序后按相等值分 tie 组取平均秩，以动态规划枚举 A 侧（baseline）从各 tie
// 组中选取 k 个的组合数，得到 A 侧秩和 R 的精确分布，双侧 p 为
// min(1, P(R <= R_obs) + P(R >= R_obs))（离散两侧概率和，连续情形即 2 倍尾概率）。
// 大样本用 tie 校正正态近似并做连续性校正：
//   z = (|U - n1*n2/2| - 0.5) / sigma，sigma^2 含 Σ(t^3-t) tie 修正，
//   双侧 p = erfc(z / sqrt(2))。

const MW_EXACT_LIMIT = 30;

// 互补误差函数 erfc(x)，Abramowitz-Stegun 7.1.26（相对误差 < 1.5e-7）。
// 仅用于大样本正态近似尾概率。
function erfc(x) {
  const z = Math.abs(x);
  const t = 1 / (1 + 0.5 * z);
  const tau = t * Math.exp(
    -z * z - 1.26551223
      + t * (1.00002368
        + t * (0.37409196
          + t * (0.09678418
            + t * (-0.18628806
              + t * (0.27886807
                + t * (-1.13520398
                  + t * (1.48851587
                    + t * (-0.82215223
                      + t * 0.17087277)))))))),
  );
  return x >= 0 ? tau : 2 - tau;
}

// 返回双侧 p 值（内部原始值，未取整）。baseline/candidate 均为数值数组，
// 可含并列；调用方保证两侧均至少 1 个观测。
function mannWhitneyTwoSided(baseline, candidate) {
  const n1 = baseline.length;
  const n2 = candidate.length;
  const n = n1 + n2;

  // 合并排序并按相等值分 tie 组：{ value, size, avgRank }（1-based 平均秩）。
  const merged = [];
  for (const v of baseline) merged.push({ v, side: 1 });
  for (const v of candidate) merged.push({ v, side: 2 });
  merged.sort((a, b) => a.v - b.v);
  const tieGroups = [];
  for (let i = 0; i < merged.length;) {
    let j = i;
    while (j < merged.length && merged[j].v === merged[i].v) j++;
    const size = j - i;
    // 该 tie 组占据秩 i+1 .. j（1-based）
    const avgRank = ((i + 1) + j) / 2;
    let a = 0;
    for (let k = i; k < j; k++) {
      if (merged[k].side === 1) a++;
    }
    tieGroups.push({ size, avgRank, aObserved: a });
    i = j;
  }

  // 观测到的 A 侧秩和
  let rObserved = 0;
  for (const g of tieGroups) rObserved += g.aObserved * g.avgRank;

  if (n <= MW_EXACT_LIMIT) {
    // dp 按已选 A 侧个数分层：Map(chosen -> Map(秩和 -> BigInt 组合数))。
    // 最终只统计 chosen === n1 的配置，保证两侧样本数固定。
    let layers = new Map([[0, new Map([[0, 1n]])]]);
    for (const g of tieGroups) {
      const next = new Map();
      for (const [chosen, sums] of layers) {
        for (const [sum, cnt] of sums) {
          for (let k = 0; k <= g.size; k++) {
            const newChosen = chosen + k;
            if (newChosen > n1) break;
            let layer = next.get(newChosen);
            if (!layer) {
              layer = new Map();
              next.set(newChosen, layer);
            }
            const key = sum + k * g.avgRank;
            const ways = cnt * binomialBigInt(g.size, k);
            layer.set(key, (layer.get(key) || 0n) + ways);
          }
        }
      }
      layers = next;
    }
    const valid = layers.get(n1) || new Map();
    let total = 0n;
    let lowerOrEqual = 0n;
    let greaterOrEqual = 0n;
    for (const [sum, cnt] of valid) {
      total += cnt;
      if (sum <= rObserved) lowerOrEqual += cnt;
      if (sum >= rObserved) greaterOrEqual += cnt;
    }
    if (total === 0n) return 1;
    const p = Number(lowerOrEqual + greaterOrEqual) / Number(total);
    return p > 1 ? 1 : p;
  }

