// 按 UTF-8 字节序比较两个字符串（Buffer 字典序），稳定且与平台区域无关。
function compareUtf8(a, b) {
  return Buffer.compare(Buffer.from(a, 'utf8'), Buffer.from(b, 'utf8'));
