        ? 'primary_attribution' : 'insufficient_evidence',
      dimensions: dimensionsOutput,
      primary_attributions: primaryAttributions,
    },
  };
}

module.exports = {
  computeAttribution,
  parseRequestJson,
  holmAdjust,
  compareUtf8,
  InvalidAttributionInputError,
  MIN_GROUP_OBSERVATIONS,
