input.old_string:
// 解析 JSON 文本并记录所有对象上的重复键：JSON.parse 会静默以后值覆盖重复键，
// 借助 reviver 在「持有对象 -> 已见键集合」上记录重复。返回
// { value, duplicateKeys }，duplicateKeys 为 Map(持有对象 -> 第一个重复键名)，
// 调用方据此只判 samples[i].dimensions 段内的重复维度键。
function parseRequestJson(text) {
  const seenByHolder = new WeakMap();
  const duplicateKeys = new WeakMap();
  const parsed = JSON.parse(text, function (key, value) {
    if (key !== '' && (typeof this === 'object') && this !== null) {
      let seen = seenByHolder.get(this);
      if (!seen) {
        seen = new Set();
        seenByHolder.set(this, seen);
      }
      if (seen.has(key) && !duplicateKeys.has(this)) {
        duplicateKeys.set(this, key);
      } else {
        seen.add(key);
      }
    }
    return value;
  });
  return { value: parsed, duplicateKeys };
}

