3	const fs = require('node:fs/promises');
4	const { parseArgs, EXIT_OK, EXIT_USAGE, EXIT_OUTPUT_ERROR } = require('./collect');
5	
6	// 回归归因：对一次已判定为回归的比较，按每个分类维度（build/host/scenario 等）
7	// 独立给出维度值级别的贡献排名与首要归因候选。
8	//
9	// 口径（见 README「attribute 子命令」）：
10	// - 仅纳入在基线侧与候选侧都至少有 3 个观测的维度值；不足者明细标
11	//   insufficient_samples 并跳过，不影响其他维度值/维度；
12	// - 每个有效维度值计算两侧中位数差（候选减基线）、合并样本权重（两侧样本数
13	//   之和）、Mann-Whitney U 双侧 p 值；同一维度内用 Holm 方法校正 p 值；
14	// - 贡献值 = 样本权重 × 中位数差，维度内按贡献值降序（并列按维度值 UTF-8
15	//   字节序）输出；
16	// - 维度值同时满足 贡献值为正、校正后 p 值 < 0.05、贡献值不低于该维度正贡献
17	//   之和的 30% 才具备首要归因资格；全局最高贡献在 1e-12 精度内并列时，并列者
18	//   全部列为首要归因候选（按维度值 UTF-8 字节序稳定排序）；
19	// - 没有任何维度值达到条件时 evidence_status 为 insufficient_evidence（非异常）。
20	
21	const { round6, mannWhitneyTwoSided } = require('./stats');
22	const {
23	  buildCompareResult, decide, DEFAULT_ALPHA, DEFAULT_MIN_CHANGE_PERCENT,
24	} = require('./compare');
25	
26	const MIN_GROUP_OBSERVATIONS = 3;
27	const SIGNIFICANCE = 0.05;
28	const PRIMARY_SHARE = 0.3;
29	const TIE_EPSILON = 1e-12;
30	
31	class InvalidAttributionInputError extends Error {
32	  constructor(path, reason) {
33	    super(`${path}: ${reason}`);
34	    this.name = 'InvalidAttributionInputError';
35	    this.path = path;
36	  }
37	}
38	
39	// 非负有限数字（不接受布尔/NaN/Infinity/字符串）。
40	function isFiniteNumber(v) {
41	  return typeof v === 'number' && Number.isFinite(v);
42	}
43	
44	// 按 UTF-8 字节序比较两个字符串（Buffer 字典序），稳定且与平台区域无关。
45	function compareUtf8(a, b) {
46	  return Buffer.compare(Buffer.from(a, 'utf8'), Buffer.from(b, 'utf8'));
47	}
48	
49	// 合法标识符直接拼接，其他键名以 JSON 字符串括号表示（与字段路径格式一致）。
50	function formatKey(key) {
51	  return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(key) ? key : `[${JSON.stringify(key)}]`;
52	}
53	
54	// JSON.parse 在当前 V8 上会先合并重复键再调用 reviver，无法借 reviver 检测。
55	// 改为在 JSON.parse 成功后对原文做一次轻量结构扫描（假定语法合法），返回首个
56	// 位于某个 samples[i].dimensions 对象内的重复键路径，如
57	// "samples[0].dimensions.host"；没有则返回 null。其他位置的重复键不视为
58	// 维度键重复（需求只禁止同一样本同一维度有多个值）。
59	function findDuplicateDimensionKey(text) {
60	  let pos = 0;
61	  const n = text.length;
62	  let found = null;
63	
64	  const ws = () => { while (pos < n && /\s/.test(text[pos])) pos++; };
65	
66	  const parseStringValue = () => {
67	    pos++; // 开引号
68	    let out = '';
69	    while (pos < n) {
70	      const c = text[pos++];
71	      if (c === '"') break;
72	      if (c === '\\') {
73	        const e = text[pos++];
74	        if (e === 'u') {
75	          out += String.fromCharCode(parseInt(text.slice(pos, pos + 4), 16));
76	          pos += 4;
77	        } else {
78	          out += { '"': '"', '\\': '\\', '/': '/', b: '\b', f: '\f', n: '\n', r: '\r', t: '\t' }[e] || e;
79	        }
80	      } else {
81	        out += c;
82	      }
83	    }
84	    return out;
85	  };
86	
87	  const skipPrimitive = () => {
88	    const c = text[pos];
89	    if (c === '"') { parseStringValue(); return; }
90	    while (pos < n && !',]}'.includes(text[pos]) && !/\s/.test(text[pos])) pos++;
91	  };
92	
93	  const DIM_PATH = /^\$\.samples\[\d+\]\.dimensions$/;
94	
95	  function parseValue(path) {
96	    ws();
97	    const c = text[pos];
98	    if (c === '{') { parseObject(path); return; }
99	    if (c === '[') { parseArray(path); return; }
100	    skipPrimitive();
101	  }
102	
103	  function parseObject(path) {
104	    pos++; // {
105	    ws();
106	    if (text[pos] === '}') { pos++; return; }
107	    const seen = new Set();
108	    while (true) {
109	      ws();
110	      const key = parseStringValue();
111	      ws();
112	      pos++; // :
113	      ws();
114	      const childPath = path === '$' ? `$.${formatKey(key)}` : `${path}.${formatKey(key)}`;
115	      if (seen.has(key)) {
116	        if (found === null && DIM_PATH.test(path)) found = childPath;
117	      } else {
118	        seen.add(key);
119	      }
120	      parseValue(childPath);
121	      ws();
122	      if (text[pos] === ',') { pos++; continue; }
123	      if (text[pos] === '}') { pos++; break; }
124	    }
125	  }
126	
127	  function parseArray(path) {
128	    pos++; // [
129	    ws();
130	    if (text[pos] === ']') { pos++; return; }
131	    let idx = 0;
132	    while (true) {
133	      parseValue(`${path}[${idx}]`);
134	      idx++;
135	      ws();
136	      if (text[pos] === ',') { pos++; continue; }
137	      if (text[pos] === ']') { pos++; break; }
138	    }
139	  }
140	
141	  parseValue('$');
142	  return found === null ? null : found.replace(/^\$\./, '');
143	}
144	
145	// 解析请求文本：先 JSON.parse 取值，再扫描重复维度键。
146	// 返回 { value, duplicatePath }。
147	function parseRequestJson(text) {
148	  const value = JSON.parse(text);
149	  const duplicatePath = findDuplicateDimensionKey(text);
150	  return { value, duplicatePath };
151	}
152	
153	// 中位数：偶数个取中间两值平均（与 collect/compare 口径一致）。
154	function medianOf(values) {
155	  const sorted = values.slice().sort((a, b) => a - b);
156	  const n = sorted.length;
157	  const mid = n >> 1;
158	  return n % 2 === 1 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
159	}
160	
161	// 维度内 Holm 校正：m 个原始 p 升序后记 p_(j)（j 从 1 起），
162	// q_(j) = min(1, min over k>=j (m-k+1)·p_(k))，映回原顺序。
163	// 平局先按 p 值，再按维度值 UTF-8 字节序保证稳定（同值再按维度名）。
164	function holmAdjust(entries) {
165	  const m = entries.length;
166	  const order = entries.map((entry, i) => i).sort((i, j) => {
167	    const a = entries[i];
168	    const b = entries[j];
169	    if (a.p !== b.p) return a.p - b.p;
170	    const byValue = compareUtf8(a.value, b.value);
171	    if (byValue !== 0) return byValue;
172	    return compareUtf8(a.dimension, b.dimension);
173	  });
174	  const adjusted = new Array(m);
175	  let running = Infinity;
176	  for (let pos = m - 1; pos >= 0; pos--) {
177	    const idx = order[pos];
178	    // pos（0-based）对应位次 j = pos+1，Holm 乘数为 m-j+1 = m-pos。
179	    running = Math.min(running, (m - pos) * entries[idx].p);
180	    adjusted[idx] = Math.min(1, running);
181	  }
182	  return adjusted;
183	}
184	
185	// 校验并归因。payload 为 parseRequestJson 解析出的请求对象；
186	// duplicatePath 为原文扫描出的首个重复维度键路径（无则 null）。非法时抛
187	// InvalidAttributionInputError，异常信息以字段路径开头：先必填的顶层标识，
188	// 再按 samples 下标顺序逐样本（side -> value -> dimensions 重复键 -> 各维度
189	// 键值），因此多类问题并存时报出的总是输入顺序中最早的字段路径。
190	function computeAttribution(payload, duplicatePath = null) {
191	  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
192	    throw new InvalidAttributionInputError('$', '请求体必须为 JSON 对象');
193	  }
194	
195	  if (typeof payload.metric !== 'string' || payload.metric === '') {
196	    throw new InvalidAttributionInputError('metric', '字段缺失或不是非空字符串');
197	  }
198	  if (typeof payload.comparison !== 'string' || payload.comparison === '') {
199	    throw new InvalidAttributionInputError('comparison', '字段缺失或不是非空字符串');
200	  }
201	
202	  let reqAlpha = DEFAULT_ALPHA;
203	  if (payload.alpha !== undefined) {
204	    if (!isFiniteNumber(payload.alpha) || !(payload.alpha > 0 && payload.alpha < 1)) {
205	      throw new InvalidAttributionInputError('alpha', '必须满足 0 < alpha < 1');
206	    }
207	    reqAlpha = payload.alpha;
208	  }
209	  let reqMinChangePercent = DEFAULT_MIN_CHANGE_PERCENT;
210	  if (payload.min_change_percent !== undefined) {
211	    if (!isFiniteNumber(payload.min_change_percent) || payload.min_change_percent < 0) {
212	      throw new InvalidAttributionInputError('min_change_percent', '必须为不小于 0 的数字');
213	    }
214	    reqMinChangePercent = payload.min_change_percent;
215	  }
216	
217	  if (!Array.isArray(payload.samples)) {
218	    throw new InvalidAttributionInputError('samples', '字段缺失或不是数组');
219	  }
220	
221	  let anyDimensionValue = false;
222	  // 形如 samples[3].dimensions.host -> 3
223	  const dupMatch = duplicatePath
224	    ? /^samples\[(\d+)\]\.dimensions\.(.*)$/.exec(duplicatePath) : null;
225	  const dupIndex = dupMatch ? Number(dupMatch[1]) : -1;
226	  for (let i = 0; i < payload.samples.length; i++) {
227	    const samplePath = `samples[${i}]`;
228	    const sample = payload.samples[i];
229	    if (!sample || typeof sample !== 'object' || Array.isArray(sample)) {
230	      throw new InvalidAttributionInputError(samplePath, '样本必须为对象');
231	    }
232	    if (sample.side !== 'baseline' && sample.side !== 'candidate') {
233	      throw new InvalidAttributionInputError(`${samplePath}.side`,
234	        '字段缺失或不是 "baseline" / "candidate"');
235	    }
236	    if (!('value' in sample) || !isFiniteNumber(sample.value)) {
237	      throw new InvalidAttributionInputError(`${samplePath}.value`, '样本值必须是有限数字');
238	    }
239	    if (i === dupIndex) {
240	      throw new InvalidAttributionInputError(duplicatePath,
241	        '维度键重复：每个样本在一个维度中只能有一个维度值');
242	    }
243	    if (sample.dimensions !== undefined && sample.dimensions !== null) {
244	      const dimPath = `${samplePath}.dimensions`;
245	      if (typeof sample.dimensions !== 'object' || Array.isArray(sample.dimensions)) {
246	        throw new InvalidAttributionInputError(dimPath, '必须为维度名到维度值的对象');
247	      }
248	      for (const name of Object.keys(sample.dimensions)) {
249	        const v = sample.dimensions[name];
250	        if (typeof v !== 'string') {
251	          throw new InvalidAttributionInputError(`${dimPath}.${name}`,
252	            '维度值必须是字符串');
253	        }
254	        anyDimensionValue = true;
255	      }
256	    }
257	  }
258	
259	  // 汇总两侧观测（保持输入顺序）。
260	  const sideValues = { baseline: [], candidate: [] };
261	  // dimName -> Map(value -> { baseline: [], candidate: [] })
262	  const dims = new Map();
263	  for (const sample of payload.samples) {
264	    sideValues[sample.side].push(sample.value);
265	    if (sample.dimensions && typeof sample.dimensions === 'object') {
266	      for (const [name, value] of Object.entries(sample.dimensions)) {
267	        let groups = dims.get(name);
268	        if (!groups) {
269	          groups = new Map();
270	          dims.set(name, groups);
271	        }
272	        let group = groups.get(value);
273	        if (!group) {
274	          group = { baseline: [], candidate: [] };
275	          groups.set(value, group);
276	        }
277	        group[sample.side].push(sample.value);
278	      }
279	    }
280	  }
281	
282	  if (sideValues.baseline.length < 2 || sideValues.candidate.length < 2) {
283	    throw new InvalidAttributionInputError('samples',
284	      '基线侧与候选侧都必须至少含 2 个样本');
285	  }
286	  if (!anyDimensionValue) {
287	    throw new InvalidAttributionInputError('samples', '整个请求没有任何有效维度值');
288	  }
289	
290	  // 原比较结论：按 compare 口径用同一批样本重算（不采用外部 summary），
291	  // 与归因计算相互独立；归因不改变任何阈值或既有字段。
292	  const baselineInput = { durations: sideValues.baseline };
293	  const candidateInput = { durations: sideValues.candidate };
294	  const compared = buildCompareResult(baselineInput, candidateInput, reqAlpha);
295	  const decisionResult = decide(
296	    compared.welch.p_value, reqAlpha,
297	    compared.delta.mean.percent, reqMinChangePercent,
298	  );
299	
300	  // 各维度独立归因。
301	  const dimensionResults = [];
302	  // 跨维度通过三道门的资格行，供全局取最高与并列判定。
303	  const eligibleRows = [];
304	
305	  for (const [dimension, groups] of dims) {
306	    const effective = [];
307	    const insufficient = [];
308	    for (const [value, group] of groups) {
309	      if (group.baseline.length >= MIN_GROUP_OBSERVATIONS
310	        && group.candidate.length >= MIN_GROUP_OBSERVATIONS) {
311	        effective.push({ value, group });
312	      } else {
313	        insufficient.push({ value, group });
314	      }
315	    }
316	
317	    const rows = effective.map(({ value, group }) => {
318	      const baselineMedian = medianOf(group.baseline);
319	      const candidateMedian = medianOf(group.candidate);
320	      const medianDiff = candidateMedian - baselineMedian;
321	      const weight = group.baseline.length + group.candidate.length;
322	      const contribution = weight * medianDiff;
323	      const p = mannWhitneyTwoSided(group.baseline, group.candidate);
324	      return {
325	        dimension,
326	        value,
327	        baselineCount: group.baseline.length,
328	        candidateCount: group.candidate.length,
329	        medianDiff,
330	        weight,
331	        contribution,
332	        p,
333	      };
334	    });
335	
336	    const adjusted = holmAdjust(rows);
337	    for (let i = 0; i < rows.length; i++) rows[i].adjustedP = adjusted[i];
338	
339	    const positiveSum = rows.reduce(
340	      (acc, row) => acc + (row.contribution > 0 ? row.contribution : 0), 0,
341	    );
342	
343	    for (const row of rows) {
344	      const adjustedRounded = round6(row.adjustedP);
345	      const qualified = row.contribution > 0
346	        && adjustedRounded < SIGNIFICANCE
347	        && positiveSum > 0
348	        && row.contribution >= PRIMARY_SHARE * positiveSum;
349	      if (qualified) eligibleRows.push(row);
350	    }
351	
352	    // 维度内排序：贡献降序；贡献在 1e-12 精度内并列按维度值 UTF-8 字节序
353	    // （与首要归因的并列口径一致，保证明细顺序与 primary_attributions 协调）。
354	    rows.sort((a, b) => {
355	      if (Math.abs(a.contribution - b.contribution) > TIE_EPSILON) {
356	        return b.contribution - a.contribution;
357	      }
358	      return compareUtf8(a.value, b.value);
359	    });
360	
361	    // 样本不足的维度值不参与排名/校正，仅在明细末尾按 UTF-8 字节序列出。
362	    const insufficientRankings = insufficient.map(({ value, group }) => ({
363	      value,
364	      baselineCount: group.baseline.length,
365	      candidateCount: group.candidate.length,
366	      insufficient: true,
367	    }));
368	    insufficientRankings.sort((a, b) => compareUtf8(a.value, b.value));
369	
370	    dimensionResults.push({ dimension, positiveSum, rows, insufficientRankings });
371	  }
372	
373	  // 维度顺序按维度名 UTF-8 字节序稳定排列（与维度首次出现顺序无关）。
374	  dimensionResults.sort((a, b) => compareUtf8(a.dimension, b.dimension));
375	
376	  // 全局首要归因：资格行中贡献最高者；与最高在 1e-12（绝对值）内并列者全部保留。
377	  let primaryRows = [];
378	  if (eligibleRows.length > 0) {
379	    const highest = eligibleRows.reduce(
380	      (m, row) => (row.contribution > m ? row.contribution : m), -Infinity,
381	    );
382	    primaryRows = eligibleRows
383	      .filter((row) => Math.abs(row.contribution - highest) <= TIE_EPSILON);
384	  }
385	  const primaryKey = new Set(primaryRows.map((row) => `${row.dimension}\u0000${row.value}`));
386	
387	  const dimensionsOutput = dimensionResults.map(({
388	    dimension, positiveSum, rows, insufficientRankings,
389	  }) => {
390	    const rankings = rows.map((row) => {
391	      const isPrimary = primaryKey.has(`${row.dimension}\u0000${row.value}`);
392	      return {
393	        value: row.value,
394	        baseline_count: row.baselineCount,
395	        candidate_count: row.candidateCount,
396	        median_diff: round6(row.medianDiff),
397	        weight: row.weight,
398	        contribution: round6(row.contribution),
399	        adjusted_p_value: round6(row.adjustedP),
400	        evidence: isPrimary
401	          ? 'primary'
402	          : eligibleRows.includes(row) ? 'eligible' : 'ranked',
403	      };
404	    });
405	    for (const item of insufficientRankings) {
406	      rankings.push({
407	        value: item.value,
408	        baseline_count: item.baselineCount,
409	        candidate_count: item.candidateCount,
410	        median_diff: null,
411	        weight: null,
412	        contribution: null,
413	        adjusted_p_value: null,
414	        evidence: 'insufficient_samples',
415	      });
416	    }
417	    const primaryCandidates = rankings
418	      .filter((row) => row.evidence === 'primary')
419	      .map((row) => row.value);
420	    return {
421	      dimension,
422	      positive_contribution_sum: round6(positiveSum),
423	      primary_candidates: primaryCandidates,
424	      rankings,
425	    };
426	  });
427	
428	  // 首要归因列表：按维度值 UTF-8 字节序，同值跨维度再按维度名字节序。
429	  const primaryAttributions = primaryRows
430	    .slice()
431	    .sort((a, b) => {
432	      const byValue = compareUtf8(a.value, b.value);
433	      if (byValue !== 0) return byValue;
434	      return compareUtf8(a.dimension, b.dimension);
435	    })
436	    .map((row) => ({
437	      dimension: row.dimension,
438	      value: row.value,
439	      median_diff: round6(row.medianDiff),
440	      weight: row.weight,
441	      contribution: round6(row.contribution),
442	      adjusted_p_value: round6(row.adjustedP),
443	    }));
444	
445	  return {
446	    metric: payload.metric,
447	    comparison: payload.comparison,
448	    baseline_summary: compared.baselineSummary,
449	    candidate_summary: compared.candidateSummary,
450	    welch: compared.welch,
451	    decision: decisionResult,
452	    attribution: {
453	      evidence_status: primaryAttributions.length > 0
454	        ? 'primary_attribution' : 'insufficient_evidence',
455	      dimensions: dimensionsOutput,
456	      primary_attributions: primaryAttributions,
457	    },
458	  };
459	}
460	
461	// attribute 子命令入口：attribute --request <归因请求.json> --output <结果.json>。
462	// 参数/输入无效时 stderr 输出一条原因（含首个问题字段路径）、退出码 2，
463	// 不创建或改写 --output；输出写入失败退出码 4；成功退出码 0。
464	async function attribute(tokens) {
465	  const KNOWN = new Set(['request', 'output']);
466	  const { values, error: parseError } = parseArgs(tokens, KNOWN);
467	  if (parseError) {
468	    process.stderr.write(`perf-regress: ${parseError}\n`);
469	    return EXIT_USAGE;
470	  }
471	  const requestPath = values.request;
472	  const output = values.output;
473	  if (requestPath === undefined || requestPath === '') {
474	    process.stderr.write('perf-regress: --request 不能为空\n');
475	    return EXIT_USAGE;
476	  }
477	  if (output === undefined || output === '') {
478	    process.stderr.write('perf-regress: --output 不能为空\n');
479	    return EXIT_USAGE;
480	  }
481	
482	  let text;
483	  try {
484	    text = await fs.readFile(requestPath, 'utf8');
485	  } catch (err) {
486	    process.stderr.write(
487	      `perf-regress: 无法读取 --request 文件 ${requestPath}: ${err.message}\n`,
488	    );
489	    return EXIT_USAGE;
490	  }
491	
492	  let payload;
493	  let duplicatePath = null;
494	  try {
495	    ({ value: payload, duplicatePath } = parseRequestJson(text));
496	  } catch {
497	    process.stderr.write(
498	      `perf-regress: 归因请求文件不是合法 JSON: ${requestPath}\n`,
499	    );
500	    return EXIT_USAGE;
501	  }
502	
503	  let result;
504	  try {
505	    result = computeAttribution(payload, duplicatePath);
506	  } catch (err) {
507	    if (err instanceof InvalidAttributionInputError) {
508	      process.stderr.write(`perf-regress: 归因输入无效: ${err.message}\n`);
509	      return EXIT_USAGE;
510	    }
511	    throw err;
512	  }
513	
514	  let outText;
515	  try {
516	    outText = JSON.stringify(result, null, 2) + '\n';
517	  } catch (err) {
518	    process.stderr.write(`perf-regress: 结果序列化失败: ${err.message}\n`);
519	    return EXIT_OUTPUT_ERROR;
520	  }
521	  try {
522	    await fs.writeFile(output, outText, 'utf8');
523	  } catch (err) {
524	    process.stderr.write(
525	      `perf-regress: 无法写入 --output ${output}: ${err.message}\n`,
526	    );
527	    return EXIT_OUTPUT_ERROR;
528	  }
529	  return EXIT_OK;
530	}
531	
532	module.exports = {
533	  attribute,
534	  computeAttribution,
535	  parseRequestJson,
536	  holmAdjust,
537	  compareUtf8,
538	  medianOf,
539	  InvalidAttributionInputError,
540	  MIN_GROUP_OBSERVATIONS,
541	  SIGNIFICANCE,
542	  PRIMARY_SHARE,
543	  TIE_EPSILON,
544	};
