353	    // 该 tie 组占据秩 i+1 .. j（1-based）
354	    const avgRank = ((i + 1) + j) / 2;
355	    let a = 0;
356	    for (let k = i; k < j; k++) {
357	      if (merged[k].side === 1) a++;
358	    }
359	    tieGroups.push({ size, avgRank, aObserved: a });
360	    i = j;
361	  }
362	
363	  // 观测到的 A 侧秩和
364	  let rObserved = 0;
365	  for (const g of tieGroups) rObserved += g.aObserved * g.avgRank;
366	
367	  if (n <= MW_EXACT_LIMIT) {
368	    // dp 按已选 A 侧个数分层：Map(chosen -> Map(秩和 -> BigInt 组合数))。
369	    // 最终只统计 chosen === n1 的配置，保证两侧样本数固定。
370	    let layers = new Map([[0, new Map([[0, 1n]])]]);
