//   双侧 p = erfc(z / sqrt(2))。
//
// 精确计数用 Number：恒为非负计数的线性累加（无抵消），比值相对误差约
// O(n·eps)；仅当计数超过安全范围（MW_EXACT_COUNT_MAX）时才回退，避免大组合数
// 下整数舍入放大。

const MW_EXACT_TRANSITION_BUDGET = 250_000;
const MW_EXACT_COUNT_MAX = 1e15;

// 互补误差函数 erfc(x)，Abramowitz-Stegun 7.1.26（相对误差 < 1.5e-7）。
// 仅用于大样本正态近似尾概率。
function erfc(x) {
  const z = Math.abs(x);
  const t = 1 / (1 + 0.5 * z);
  const tau = t * Math.exp(
    -z * z - 1.26551223
      + t * (1.00002368
        + t * (0.37409196
          + t * (0.09678418
            + t * (-0.18628806
              + t * (0.27886807
                + t * (-1.13520398
                  + t * (1.48851587
                    + t * (-0.82215223
                      + t * 0.17087277)))))))),
  );
  return x >= 0 ? tau : 2 - tau;
}

// 组合数 C(n, k)（Number）。仅在小 n 上调用，调用方另做溢出检查。
function binomialCount(n, k) {
  if (k < 0 || k > n) return 0;
  const kk = Math.min(k, n - k);
  let num = 1;
  let den = 1;
  for (let i = 0; i < kk; i++) {
    num *= n - i;
    den *= i + 1;
  }
  return num / den;
}

